const e="Narcissistic Personality Disorder | Michelle Barratt Psychology",i="Narcissistic Personality Disorder (NPD) therapy requires specialised, structured support focused on building healthier relationships, emotional regulation, an",t='<!--$--><section class="bg-gradient-to-br from-plum to-rose text-white"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20"><div><nav aria-label="Breadcrumb" class="mb-6"><ol class="flex flex-wrap items-center gap-2 text-[12px] uppercase tracking-[0.14em] text-white/75"><li><a class="hover:text-white" href="/">Home</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li><a class="hover:text-white active" href="/therapy-services" data-status="active" aria-current="page">Therapy Services</a></li><li aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3 w-3"><path d="m9 18 6-6-6-6"></path></svg></li><li class="text-white" aria-current="page">Narcissistic Personality Disorder</li></ol></nav><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-white/85 mb-3">Specialised Therapy</p><h1 class="text-white text-[32px] md:text-[44px] font-semibold leading-[1.08] max-w-3xl">Narcissistic Personality Disorder Therapy</h1><div class="h-[3px] w-16 bg-sun my-5" aria-hidden="true"></div><div class="max-w-2xl text-[16px] md:text-[17px] text-white/95 space-y-3"><p>Narcissistic Personality Disorder (NPD) therapy requires specialised, structured support focused on building healthier relationships, emotional regulation, and long-term personal growth.</p><p>Michelle Barratt Psychology Administrative Services connects clients with experienced Brisbane psychologists and online Australia-wide practitioners who provide evidence-based therapy and treatment tailored to complex personality and interpersonal challenges.</p></div><div class="mt-6 flex flex-wrap gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-white text-plum hover:bg-blush " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-white/70 text-white hover:bg-white/10 " href="/practitioners">See Practitioners</a></div></div></div></section><section class="bg-soft !py-0"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="py-14 md:py-16"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2023/02/pexels-rodnae-productions-6517116.jpg" alt="Pexels Rodnae Productions 6517116" class="w-full aspect-[16/9] max-h-[520px] object-cover rounded border border-lilac"/></div></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Narcissistic Personality Disorder Therapy</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt Psychology &amp; Administrative Support (MBP) provides a clinically informed administrative hub that establishes the firm boundaries and professional rigor necessary for complex psychological work. We support independent Brisbane psychologists and allied health practitioners by managing the logistical framework required to treat Narcissistic Personality Disorder (NPD) and associated interpersonal challenges effectively.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Michelle Barratt Psychology (MBP) provides in-person therapy across Brisbane, and flexible online therapy Australia-wide, ensuring your journey to healing remains consistent and accessible.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How does MBP support Complex Clinical Care?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Working with personality-related challenges often requires consistency, clear boundaries, and careful coordination. MBP provides the administrative structure that allows practitioners to focus fully on therapeutic care while ensuring clients experience a professional and organised pathway into treatment.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">From intake and practitioner matching through to scheduling, referrals, and ongoing support, our administrative processes are designed to support the high standards required for long-term psychological intervention and personal growth.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What support does MBP provide?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Boundary Management</h3><p class="text-[15px] leading-relaxed text-ink/85">Clear administrative protocols help establish professional boundaries and support a consistent therapeutic framework.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Specialised Triage</h3><p class="text-[15px] leading-relaxed text-ink/85">Clinically informed intake helps connect individuals with practitioners experienced in treating personality disorders.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Consistent Communication</h3><p class="text-[15px] leading-relaxed text-ink/85">MBP provides a reliable and neutral point of contact for scheduling, enquiries, and administrative matters.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Referral Precision</h3><p class="text-[15px] leading-relaxed text-ink/85">Documentation, referrals, and care coordination are managed accurately to support ongoing treatment needs.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Integrated Support</h3><p class="text-[15px] leading-relaxed text-ink/85">Administrative coordination helps maintain continuity across psychologists, GPs, psychiatrists, and allied health providers.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">Structured Access</h3><p class="text-[15px] leading-relaxed text-ink/85">Brisbane-based and online Australia-wide appointment options support ongoing engagement in therapy.</p></div></div></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How do I get started?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are seeking specialised assistance for yourself or a loved one, please email us using the form below or contact us . Our administrative team will guide you through the intake process and connect you with a Brisbane psychologist or practitioner suited to these complex clinical needs.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Explore Our Clinicians:</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">You may also view our Practitioner Page and select the clinician of your choice.</p><h3 class="text-2xl font-semibold mt-8 mb-3">Important safety note</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If you are in immediate danger, experiencing severe distress, or having thoughts of harming yourself, contact emergency services or a crisis service right away. If you are concerned but not in immediate danger, please mention this when you contact us so we can prioritise an appropriate, timely response.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What is Narcissistic Personality Disorder?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Narcissistic Personality Disorder is a complex mental health condition that can influence how individuals view themselves, relate to others, and respond to life&#x27;s challenges. While confidence and ambition can be healthy traits, NPD often involves greater difficulties with self-esteem, emotional regulation, interpersonal relationships, and sensitivity to criticism.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Many people living with NPD experience significant challenges in personal, family, social, or workplace relationships, even when these difficulties are not immediately apparent.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">How can NPD affect everyday life?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">The impact of NPD can vary between individuals, but common challenges may include relationship conflict, difficulty accepting feedback, emotional reactions to perceived criticism, struggles with vulnerability, and ongoing concerns about self-worth or validation.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">These patterns can affect friendships, intimate relationships, family dynamics, workplace interactions, and overall emotional well-being. Therapy aims to help individuals develop healthier ways of understanding themselves and relating to others.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">What does NPD therapy focus on?</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Treatment for Narcissistic Personality Disorder is typically a long-term process that focuses on increasing self-awareness, strengthening emotional regulation, and improving interpersonal functioning. Depending on individual needs, therapy may incorporate Cognitive Behavioural Therapy (CBT), Schema Therapy, psychodynamic approaches, Acceptance and Commitment Therapy (ACT), and other evidence-based interventions.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Therapy provides a supportive environment where individuals can explore patterns of thinking, behaviour, and relationships while developing healthier coping strategies.</p><h3 class="text-2xl font-semibold mt-8 mb-3">Dialectical Behaviour Therapy</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">A specialised form of therapy that focuses on teaching skills to manage intense emotions, reduce self-destructive behaviours, and improve relationships. It combines mindfulness, emotional regulation, distress tolerance, and interpersonal effectiveness principles to help individuals navigate their emotional landscape more effectively.</p><h3 class="text-2xl font-semibold mt-8 mb-3">Cognitive Behaviour Therapy</h3><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">A widely used therapy that aims to identify and change negative thought patterns and behaviours. It helps individuals understand the connection between their thoughts, feelings, and actions and develop strategies to cope with challenging emotions and situations.</p></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Building healthier relationships and self-understanding</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">One of the key goals of NPD therapy is helping individuals build a more stable and realistic sense of self. Rather than relying heavily on external validation, therapy encourages the development of internal confidence, emotional resilience, and healthier interpersonal skills.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Key areas often explored include:</p><ul class="max-w-3xl space-y-2.5 my-6"><li class="flex gap-3 text-[17px] leading-relaxed text-ink/90"><span class="mt-[10px] h-1.5 w-1.5 shrink-0 rounded-full bg-rose" aria-hidden="true"></span><span>Emotional regulation and managing reactions to criticism • Vulnerability and self-awareness • Empathy and perspective-taking • Relationship skills and interpersonal effectiveness • Identity development and self-worth • Long-term personal growth and resilience</span></li></ul><figure class="my-9"><img src="https://michellebarrattpsychology.com.au/wp-content/uploads/2026/05/38882.jpg" alt="38882" loading="lazy" class="w-full max-w-4xl aspect-[3/2] object-cover rounded border border-lilac"/></figure><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Healthy boundaries, education, and support can help families maintain their own wellbeing while navigating complex relationship dynamics.</p></div></section><section class="bg-white "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Supporting a Loved One Living with NPD</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Living with or caring about someone who experiences narcissistic personality traits can be challenging and emotionally demanding. Family members, partners, and close friends may experience confusion, frustration, relationship strain, or uncertainty about how best to provide support.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Professional guidance can help families better understand personality-related challenges while developing healthier communication patterns and boundaries that support everyone involved.</p><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 my-8"><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">1 Understanding NPD</h3><p class="text-[15px] leading-relaxed text-ink/85">Learn about personality patterns, emotional responses, and how NPD may affect relationships.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">2 Healthy Boundaries</h3><p class="text-[15px] leading-relaxed text-ink/85">Develop practical boundaries that support respectful and sustainable relationships.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">3 Effective Communication</h3><p class="text-[15px] leading-relaxed text-ink/85">Build communication skills that reduce conflict and encourage healthier interactions.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">4 Relationship Support</h3><p class="text-[15px] leading-relaxed text-ink/85">Gain practical tools for navigating complex family, partner, or social relationships.</p></div><div class="bg-white/70 rounded border border-lilac p-6"><span class="block h-2.5 w-2.5 rounded-full bg-ocean mb-4" aria-hidden="true"></span><h3 class="text-xl font-semibold mb-2">5 Professional Guidance</h3><p class="text-[15px] leading-relaxed text-ink/85">Access experienced psychologists who can support both individuals and families affected by NPD.</p></div></div></div></section><section class="bg-soft "><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><div class="mb-10 max-w-3xl"><h2 class="text-3xl md:text-4xl font-semibold">Contact Us on the Email Form Below</h2><div class="h-[3px] w-14 bg-sun mt-5" aria-hidden="true"></div></div><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">Please be advised that you&#x27;ll receive a response within 24 to 48 hours.</p><p class="max-w-3xl text-[17px] leading-[1.75] text-ink/90 mb-5">If in crisis, please call 000.</p></div></section><section class="bg-lilac !py-14"><div class="mx-auto max-w-7xl px-5 py-14 md:py-20 "><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-4">More in <!-- -->Specialised Therapy</p><ul class="flex flex-wrap gap-3"><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/borderline-personality-disorder">Borderline Personality Disorder<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/bipolar-disorder">Bipolar Disorder<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/personality-disorders">Personality Disorders<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/diabetes">Diabetes Mental Health Support<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/psychodynamic-therapy">Psychodynamic Therapy<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li><li><a class="inline-flex items-center gap-2 bg-white border border-lilac rounded px-4 py-2.5 text-[14px] font-medium text-ink transition-colors hover:border-ocean hover:text-ocean" href="/therapy-services/eating-disorders">Eating Disorders<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-chevron-right h-3.5 w-3.5" aria-hidden="true"><path d="m9 18 6-6-6-6"></path></svg></a></li></ul></div></section><section class="bg-blush"><div class="mx-auto max-w-4xl px-5 py-14 md:py-16 text-center"><p class="text-[12px] font-semibold uppercase tracking-[0.2em] text-rose mb-2.5">Take the first step</p><h2 class="text-[30px] md:text-[40px] font-semibold leading-[1.1]">Ready to Take the First Step?</h2><div class="h-[3px] w-14 bg-sun mt-4 mx-auto" aria-hidden="true"></div><p class="mt-5 text-[17px]">Seeking support can feel overwhelming, but you do not have to navigate life&#x27;s challenges alone. Our administration team can help answer your questions, explain appointment options and connect you with a suitable practitioner.</p><p class="mt-3">Prefer to call? Phone our administration team on <a class="text-ocean underline underline-offset-4 font-medium" href="tel:0731850040">07 3185 0040</a>.</p><div class="mt-7 flex flex-wrap justify-center gap-3"><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-rose text-white hover:bg-[#9d2a59] " href="/practitioners">Book Online</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 bg-ocean text-white hover:bg-[#095a6f] " href="/contact">Contact Us</a><a class="inline-flex items-center justify-center min-h-12 px-7 rounded whitespace-nowrap text-[13px] font-semibold uppercase tracking-[0.12em] transition-colors duration-300 border border-plum text-plum hover:bg-lilac  active" href="/therapy-services" data-status="active" aria-current="page">Explore Services</a></div><p class="mt-5 text-sm text-ink/70">If in crisis, please call 000.</p></div></section><!--/$-->',a={title:e,description:i,html:t};export{a as default,i as description,t as html,e as title};
